function closest(node, tag, root) {
  for (let n = node; n; n = n.parent) {
    if (n.tag === tag) return n
    if (n === root) return null
  }
  return null
}
function delegate(root, tag, handler) {
  return (event) => {
    const match = closest(event.target, tag, root)
    if (match) handler(match, event)
  }
}

