function createStore(storage, ns) {
  const k = (key) => `${ns}:${key}`
  return {
    set(key, value, ttlMs) {
      storage.setItem(k(key), JSON.stringify({ v: value, exp: ttlMs ? Date.now() + ttlMs : null }))
    },
    get(key, fallback) {
      const raw = storage.getItem(k(key))
      if (raw === null) return fallback
      try {
        const { v, exp } = JSON.parse(raw)
        if (exp !== null && Date.now() > exp) { storage.removeItem(k(key)); return fallback }
        return v
      } catch {
        storage.removeItem(k(key)); return fallback
      }
    },
  }
}

