async function cacheFirst(url, cache, fetchImpl) {
  if (cache.has(url)) return cache.get(url)
  const v = await fetchImpl(url)
  cache.set(url, v)
  return v
}
async function staleWhileRevalidate(url, cache, fetchImpl) {
  const fresh = fetchImpl(url).then((v) => { cache.set(url, v); return v })
  if (cache.has(url)) { fresh.catch(() => {}); return cache.get(url) }
  return fresh
}
